import scipy.optimize as so
def basis3(w,mode):
    if mode==0:
        tc=[np.cos(k*w*t) for k in (1,2,3)]+[np.sin(k*w*t) for k in (1,2,3)]
    else:
        g=np.exp(-mode*t)
        tc=[np.cos(w*t)*g,np.sin(w*t)*g,np.cos(w*t),np.sin(w*t)]
    cols=tc+[np.ones(len(t))]
    for i in range(4):
        for j in range(4):
            if i+j<=3: cols.append(x**i*v**j)
    return np.column_stack(cols)
